// node xr/tools/extract-boats.mjs [--check]
// The boats station reuses the boats page's own code instead of a rewrite, and the boats page stays untouched:
//   stations/boats/ais-core.js  <- the AIS core script block (parsing, LOC rules, AREAS, card helpers), as an ES module
//   stations/boats/ships3d.js   <- the ship kit from createScene(): water, sky, materials, the per-type ship builders,
//                                  wakes, labels, sea motion (createShipKit(THREE, C, { scene, renderer, CAT_COLORS }))
// Re-run after boats/index.html changes. --check exits 1 when the generated files are out of date (used by xr/test).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const SRC = path.join(ROOT, 'boats/index.html');
const OUT = path.join(ROOT, 'stations/boats');
const html = fs.readFileSync(SRC, 'utf8');
const lines = html.split('\n');

function between(startMark, endMark, from = 0) {
  const a = lines.findIndex((l, i) => i >= from && l.includes(startMark));
  if (a < 0) throw new Error('marker not found: ' + startMark);
  const b = lines.findIndex((l, i) => i > a && l.includes(endMark));
  if (b < 0) throw new Error('marker not found: ' + endMark);
  return { a, b, text: lines.slice(a, b).join('\n') };
}

// ---- 1) AIS core (a classic script that sets root.AISCore)
const core = between('/* AIS core: parsing', '</script>');
let coreText = core.text.replace(/\}\)\(typeof window !== 'undefined' \? window : globalThis\);\s*$/, '})(__root);');
if (!coreText.includes('})(__root);')) throw new Error('AIS core: unexpected ending');
const aisCore = `// GENERATED by xr/tools/extract-boats.mjs from boats/index.html (the "AIS core" script). Do not edit here:
// change boats/index.html, then run: node xr/tools/extract-boats.mjs
const __root = {};
${coreText}
export const AISCore = __root.AISCore;
export default AISCore;
`;

// ---- 2) the ship kit (inside createScene)
const cs = lines.findIndex((l) => l.startsWith('function createScene(THREE, OrbitControls, hooks)'));
if (cs < 0) throw new Error('createScene not found');
const A = between('/* Shader helper: custom shaders', '/* satellite tiles: land', cs);
const B = between('/* satellite tiles: land', 'const vessels = new Map();', cs);
const C = between('/* ----- shared materials and textures', '  function updateVessels(', cs);
// zero allocations in the frame loop: the wave sum runs per ship per frame, so no closure there
const WAVE_FE = 'wavesJS.forEach((w, i) => { h += w[3] * Math.sin(w[0] * x + w[1] * z - w[2] * t) * (1 - sstep(WFADE[i] * 0.6, WFADE[i], r)); });';
if (!A.text.includes(WAVE_FE)) throw new Error('waveHeight changed: update the loop rewrite');
A.text = A.text.replace(WAVE_FE, 'for (let i = 0; i < wavesJS.length; i++) { const w = wavesJS[i]; h += w[3] * Math.sin(w[0] * x + w[1] * z - w[2] * t) * (1 - sstep(WFADE[i] * 0.6, WFADE[i], r)); }');
const kit = `// GENERATED by xr/tools/extract-boats.mjs from boats/index.html (createScene: water, sky, ship builders, wakes, sea motion).
// Do not edit here: change boats/index.html, then run: node xr/tools/extract-boats.mjs
// createShipKit(THREE, C, { scene, renderer, CAT_COLORS }) -> the pieces below. scene: the group the sky and the sea go in
// (the station's root). Shared materials / textures / geometries are marked userData.shared; dispose() frees everything.
export function createShipKit(THREE, C, { scene, renderer, CAT_COLORS }) {
  const HORIZON = new THREE.Color(0xc9dcea), ZENITH = new THREE.Color(0x3f7fc4);
  const SUN_DIR = new THREE.Vector3(-0.62, 0.5, 0.6).normalize();   // afternoon sun from the south-west
  const vessels = new Map();   // (unused by the builders; clear() / removeVessel() below expect it)
${A.text}
${B.text}
${C.text}
  function dispose() {
    [sky, nearWater, farWater].forEach((m) => { m.removeFromParent(); m.geometry.dispose(); m.material.dispose(); });
    tileGroup.removeFromParent();
    Object.values(MAT).forEach((m) => { if (m.map) m.map.dispose(); m.dispose(); });
    winTex.dispose(); containerTex.dispose(); unitBox.dispose(); wakeGeom.dispose();
  }
  return { HORIZON, ZENITH, SUN_DIR, uTime, sky, nearWater, farWater, tileGroup, tileMaterial, maxAniso, uPatch, patch, PATCH_HALF,
    waveHeight, buildModel, disposeGroup, seaMotion, labelSprite, MAT, hash, dispose };
}
`;

const files = { 'ais-core.js': aisCore, 'ships3d.js': kit };
const check = process.argv.includes('--check');
let stale = 0;
for (const [name, text] of Object.entries(files)) {
  const p = path.join(OUT, name);
  const old = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : '';
  if (old === text) { console.log('up to date: stations/boats/' + name); continue; }
  if (check) { stale++; console.log('STALE: stations/boats/' + name + ' (run node xr/tools/extract-boats.mjs)'); continue; }
  fs.writeFileSync(p, text); console.log('wrote stations/boats/' + name + ' (' + text.length + ' bytes)');
}
if (check && stale) process.exit(1);
